 <div class="mission panel"><div class="label">Priority / 01</div><div class="title">The clock is broken.</div><p>Find the stranded courier in the old quarter. Survive the night. The rift can take you somewhere safer—or much worse.</p><div class="objective" id="objective">◈ Locate the courier · 240m</div></div><div class="toast" id="toast">SIGNAL ACQUIRED</div><div class="controls">MOVE <span class="key">WASD</span> &nbsp; ATTACK <span class="key">CLICK</span><br>ROLL <span class="key">SPACE</span> &nbsp; INTERACT <span class="key">E</span><br>TIME SHIFT <span class="key">Q</span> &nbsp; ENTER/EXIT CAR <span class="key">F</span></div>
 <div class="touch"><div class="joystick" id="joy"><div class="joydot" id="joydot"></div></div><div class="touch-actions"><button id="shiftBtn">SHIFT<br>Q</button><button id="rollBtn">ROLL</button><button id="useBtn">USE</button><button class="big" id="attackBtn">HIT</button></div></div></div>
 <div class="start" id="start"><div class="start-inner"><div class="eyebrow">A CITY BETWEEN TWO TOMORROWS</div><h1>LAST<br><em>LIGHT</em></h1><p>One city. Two timelines. The night is trying to erase itself. Scavenge, fight, and steal your way to the rift before the storm catches up.</p><button id="play">ENTER THE CITY &nbsp; ↗</button><span class="hint">WASD MOVE · CLICK ATTACK · Q TIME SHIFT · E INTERACT</span></div></div>
 <script>
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mapCanvas=document.querySelector('#map'),mctx=mapCanvas.getContext('2d');
+let W=innerWidth,H=innerHeight,DPR=1;function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);mapCanvas.width=mapCanvas.height=312;mctx.setTransform(2,0,0,2,0,0)}addEventListener('resize',resize);resize();
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+const world={size:2000,buildings:[],trees:[],crates:[],cars:[],enemies:[],rain:[],snow:[]};
+for(let ix=0;ix<5;ix++)for(let iy=0;iy<5;iy++){
+ let bx=95+ix*400,by=95+iy*400;
+ if((ix+iy)%5!==0)world.buildings.push({x:bx,y:by,w:215+((ix*iy)%3)*24,h:210+((ix+iy)%3)*20,z:rand(65,150),tone:(ix*7+iy*3)%4});
+ if((ix+iy)%3===0)world.buildings.push({x:bx+245,y:by+85,w:105,h:135,z:72,tone:(ix+iy)%4});
+}
+for(let i=0;i<48;i++){let x=rand(45,1955),y=rand(45,1955);if(!world.buildings.some(b=>x>b.x-35&&x<b.x+b.w+35&&y>b.y-35&&y<b.y+b.h+35))world.trees.push({x,y,r:rand(12,21),tone:i%3})}
+for(let i=0;i<19;i++){let x=120+(i%5)*390+rand(-25,25),y=125+Math.floor(i/5)*405+rand(-30,30);if(world.buildings.some(b=>x>b.x-20&&x<b.x+b.w+20&&y>b.y-20&&y<b.y+b.h+20))continue;world.crates.push({x,y,used:false})}
+world.cars=[{x:560,y:410,a:.3,color:'#d8ff6b',occupied:false},{x:1510,y:520,a:1.9,color:'#5bd6d0',occupied:false},{x:620,y:1430,a:-.6,color:'#f47588',occupied:false},{x:1600,y:1470,a:2.4,color:'#efa04e',occupied:false}];
+const courier={x:1250,y:670,found:false};const rift={x:930,y:800};
+for(let i=0;i<8;i++){let x=rand(460,1750),y=rand(350,1750);if(!world.buildings.some(b=>x>b.x-30&&x<b.x+b.w+30&&y>b.y-30&&y<b.y+b.h+30))world.enemies.push({x,y,hp:3,max:3,spd:rand(20,33),phase:rand(0,7),alive:true})}
+const player={x:900,y:890,hp:100,st:100,xp:0,level:1,scrap:0,face:0,swing:0,roll:0,invul:0,car:null,hit:0};
+let era=0,weather=0,gameOn=false,elapsed=0,quest=0,last=0,toastTimer=0,keys={},mouse={x:W/2,y:H/2,down:false},joy={x:0,y:0},camera={x:0,y:0},particles=[],missionPulse=0;
+const palettes=[{ground:'#24332e',grass:'#304536',road:'#363e3b',edge:'#83917b',wall:['#78817a','#60726e','#8b7669','#61706d'],roof:['#435a52','#344f50','#66544d','#3e5652'],accent:'#b6ffcf',night:'#13211f'},{ground:'#776a50',grass:'#8d815d',road:'#514d42',edge:'#c1a978',wall:['#cfab79','#8c7657','#b3a171','#88745e'],roof:['#b48150','#72614b','#9d7654','#887958'],accent:'#ffe494',night:'#423621'}];
+function iso(x,y){return {x:(x-y)*.72,y:(x+y)*.36}}function scr(x,y,z=0){let p=iso(x-camera.x,y-camera.y);return{x:W/2+p.x,y:H/2+p.y-z}}function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
+function rectDiamond(x,y,w,h,fill){poly([scr(x,y),scr(x+w,y),scr(x+w,y+h),scr(x,y+h)],fill)}
+function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}
+function levelUp(){while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.hp=100;toast('RANK UP // '+String(player.level).padStart(2,'0')+' — VITALS RESTORED')}}
+function gainXP(n){player.xp+=n;levelUp()}
+function blocked(x,y,r=12){if(x<25||y<25||x>1975||y>1975)return true;return world.buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
+function movePlayer(dx,dy,dt){let speed=player.car?220:player.roll>0?235:155;if(player.st<12&& !player.car)speed*=.75;let m=Math.hypot(dx,dy);if(m){dx/=m;dy/=m;player.face=Math.atan2(dy,dx)}if(player.roll>0){speed=280;player.st=Math.max(0,player.st-42*dt)}else player.st=Math.min(100,player.st+19*dt);let nx=clamp(player.x+dx*speed*dt,25,1975),ny=clamp(player.y+dy*speed*dt,25,1975);if(!blocked(nx,player.y,player.car?20:11))player.x=nx;if(!blocked(player.x,ny,player.car?20:11))player.y=ny}
+function attack(){if(!gameOn)return;if(player.car){toast('EXIT VEHICLE TO FIGHT');return}if(player.swing>0)return;player.swing=.34;player.st=Math.max(0,player.st-7);let target=null,best=72;for(const e of world.enemies){if(!e.alive)continue;let d=dist(player,e);let a=Math.atan2(e.y-player.y,e.x-player.x),delta=Math.atan2(Math.sin(a-player.face),Math.cos(a-player.face));if(d<best&&Math.abs(delta)<1.25){best=d;target=e}}if(target){target.hp--;target.hit=.22;let a=Math.atan2(target.y-player.y,target.x-player.x);target.x+=Math.cos(a)*22;target.y+=Math.sin(a)*22;if(target.hp<=0){target.alive=false;gainXP(35);player.scrap+=4;toast('THREAT NEUTRALIZED  +35 XP')}}}
+function interact(){if(!gameOn)return;if(!courier.found&&dist(player,courier)<65){courier.found=true;gainXP(50);toast('COURIER SECURED // RIFT SIGNAL MARKED');quest=1;return}if(quest===1&&dist(player,rift)<72){quest=2;gainXP(120);player.scrap+=15;toast('TIMELINE STABILIZED // RUN COMPLETE');return}let c=world.crates.find(c=>!c.used&&dist(player,c)<55);if(c){c.used=true;let loot=8+Math.floor(Math.random()*9);player.scrap+=loot;player.hp=clamp(player.hp+16,0,100);player.st=100;gainXP(20);toast('CACHE OPENED  +'+loot+' SCRAP / +20 XP');return}if(player.car){player.car.occupied=false;player.car=null;toast('VEHICLE ABANDONED');return}if(dist(player,rift)<80){toast('RIFT LOCKED // FIND THE COURIER');return}toast('NOTHING TO INTERACT WITH')}
+function useCar(){if(!gameOn)return;if(player.car){player.car.occupied=false;player.car=null;toast('EXITING VEHICLE');return}let car=world.cars.find(c=>!c.occupied&&dist(player,c)<62);if(car){car.occupied=true;player.car=car;toast('VEHICLE ACQUIRED // F TO EXIT')}else toast('NO VEHICLE NEARBY')}
+function shiftEra(){if(!gameOn)return;era=1-era;weather=(weather+1)%3;toast(era?'PAST // 1989 · THE LONG THAW':'FUTURE // 2089 · NEON AGE')}
+function begin(){gameOn=true;document.querySelector('#start').classList.add('hide');last=performance.now();toast('SURVIVE THE NIGHT // FIND THE COURIER')}
+document.querySelector('#play').addEventListener('click',begin);
+addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.repeat)return;if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='f')useCar();if(e.key.toLowerCase()==='q')shiftEra();if(e.key===' ')player.roll=.34;if(e.key==='Enter'&&!gameOn)begin()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+canvas.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;if(e.pointerType==='touch')return;let p=worldAt(mouse.x,mouse.y);player.face=Math.atan2(p.y-player.y,p.x-player.x)});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){mouse.down=true;attack()}});addEventListener('pointerup',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
+function worldAt(sx,sy){let x=sx-W/2,y=sy-H/2;let a=x/.72,b=y/.36;return{x:camera.x+(a+b)/2,y:camera.y+(b-a)/2}}
+const joyEl=document.querySelector('#joy'),joydot=document.querySelector('#joydot');let joyOn=false;joyEl.addEventListener('pointerdown',e=>{joyOn=true;joyEl.setPointerCapture(e.pointerId);joyMove(e)});joyEl.addEventListener('pointermove',e=>{if(joyOn)joyMove(e)});joyEl.addEventListener('pointerup',()=>{joyOn=false;joy.x=joy.y=0;joydot.style.transform='translate(0,0)'});function joyMove(e){let r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(42,Math.hypot(dx,dy));let a=Math.atan2(dy,dx);joy.x=Math.cos(a)*m/42;joy.y=Math.sin(a)*m/42;joydot.style.transform=`translate(${joy.x*35}px,${joy.y*35}px)`}
+document.querySelector('#attackBtn').addEventListener('pointerdown',attack);document.querySelector('#useBtn').addEventListener('pointerdown',interact);document.querySelector('#shiftBtn').addEventListener('pointerdown',shiftEra);document.querySelector('#rollBtn').addEventListener('pointerdown',()=>player.roll=.34);

