document.querySelector('#rollBtn').addEventListener('pointerdown',()=>player.roll=.34);
function drawGround(){
 const pal=palettes[era];ctx.fillStyle=pal.night;ctx.fillRect(0,0,W,H);
 let sx=Math.floor(camera.x/100)*100-800,sy=Math.floor(camera.y/100)*100-800;
 for(let x=Math.max(0,sx);x<Math.min(2000,sx+W*1.35+100);x+=100)for(let y=Math.max(0,sy);y<Math.min(2000,sy+H*1.35+100);y+=100){
  const mx=((x%400)+400)%400,my=((y%400)+400)%400;let road=(mx>=300&&mx<400)||(my>=300&&my<400);let sidewalk=!road&&((mx>=275&&mx<310)||(my>=275&&my<310));let fill=road?pal.road:sidewalk?pal.edge:((Math.floor(x/100)+Math.floor(y/100))%4===0?pal.grass:pal.ground);
  rectDiamond(x,y,100,100,fill);
  if(road&&Math.abs(mx-350)<1&&my>15&&my<285&&Math.floor(y/100)%2===0){let a=scr(x+49,y+16),b=scr(x+51,y+16),c=scr(x+51,y+48),d=scr(x+49,y+48);poly([a,b,c,d],era?'#b9a87577':'#a9b5a477')}
 }
 // Wet reflections and pools
 if(weather===0){ctx.save();ctx.globalAlpha=.16;for(let i=0;i<18;i++){let p=scr((Math.floor(camera.x/100)*100+(i*137)%1100),Math.floor(camera.y/100)*100+(i*197)%1100);ctx.fillStyle=i%2?'#9eeac4':'#d7efff';ctx.beginPath();ctx.ellipse(p.x,p.y+5,rand(6,23),2,Math.PI/5,0,Math.PI*2);ctx.fill()}ctx.restore()}
}
function drawBuilding(b){const p=palettes[era],c=[scr(b.x,b.y),scr(b.x+b.w,b.y),scr(b.x+b.w,b.y+b.h),scr(b.x,b.y+b.h)],top=c.map(q=>({x:q.x,y:q.y-b.z}));
 poly([c[0],c[1],top[1],top[0]],p.wall[b.tone]);poly([c[1],c[2],top[2],top[1]],p.wall[(b.tone+1)%4]);poly(top,p.roof[b.tone],'rgba(240,255,235,.16)');
 // rooftop service block and windows
 let cx=b.x+b.w*.48,cy=b.y+b.h*.48,q=scr(cx,cy,b.z+9);ctx.fillStyle=era?'#695844':'#354c48';ctx.fillRect(q.x-12,q.y-7,25,11);
 for(let i=0;i<Math.floor(b.w/65);i++){let t=(i+1)/(Math.floor(b.w/65)+1),a={x:c[0].x+(c[1].x-c[0].x)*t,y:c[0].y+(c[1].y-c[0].y)*t-b.z*.48};ctx.fillStyle=era?'#f7d27b':'#95ddca';ctx.globalAlpha=.58;ctx.fillRect(a.x-4,a.y-3,8,7);ctx.globalAlpha=1}
}
function drawTree(t){let p=scr(t.x,t.y),r=t.r;ctx.fillStyle='#0c161380';ctx.beginPath();ctx.ellipse(p.x,p.y+4,r*1.15,r*.55,0,0,7);ctx.fill();ctx.fillStyle=era?'#645c38':'#4b644c';ctx.fillRect(p.x-3,p.y-r*1.5,6,r*1.5);ctx.fillStyle=era?['#a79a57','#827945','#b3a464'][t.tone]:'#426651';ctx.beginPath();ctx.arc(p.x,p.y-r*.95,r,0,7);ctx.fill();ctx.fillStyle='#9ac08a55';ctx.beginPath();ctx.arc(p.x-r*.3,p.y-r*1.2,r*.46,0,7);ctx.fill()}
function drawCrate(c){let p=scr(c.x,c.y);ctx.fillStyle='#07100d80';ctx.fillRect(p.x-12,p.y-4,26,9);ctx.fillStyle=era?'#8f7747':'#6b826b';ctx.fillRect(p.x-10,p.y-18,20,16);ctx.fillStyle=era?'#c3a365':'#a0b79b';ctx.fillRect(p.x-9,p.y-18,18,3);ctx.fillStyle='#2e4038';ctx.fillRect(p.x-2,p.y-16,3,14);if(!c.used&&dist(player,c)<100){ctx.strokeStyle='#d8ff6b66';ctx.strokeRect(p.x-13,p.y-21,26,23)}}
function drawCar(c){let p=scr(c.x,c.y),s=player.car===c?1:1,ang=c.a;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(ang);ctx.fillStyle='#07100daa';ctx.beginPath();ctx.ellipse(0,3,26,13,0,0,7);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.moveTo(-26,-9);ctx.lineTo(15,-12);ctx.lineTo(27,-5);ctx.lineTo(23,9);ctx.lineTo(-22,10);ctx.closePath();ctx.fill();ctx.fillStyle='#253a3b';ctx.beginPath();ctx.moveTo(-11,-9);ctx.lineTo(10,-10);ctx.lineTo(17,-4);ctx.lineTo(-13,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#d7f0dc';ctx.fillRect(21,-5,3,4);ctx.restore()}
function drawActor(x,y,kind,face=0,frame=0){let p=scr(x,y);ctx.fillStyle='#07100d99';ctx.beginPath();ctx.ellipse(p.x,p.y+4,kind==='player'?12:11,6,0,0,7);ctx.fill();if(kind==='enemy'){ctx.fillStyle='#df6576';ctx.beginPath();ctx.arc(p.x,p.y-16,7,0,7);ctx.fill();ctx.fillStyle='#733943';ctx.fillRect(p.x-7,p.y-13,14,14);ctx.fillStyle='#ffb3a8';ctx.fillRect(p.x-4,p.y-19,2,2)}else{ctx.fillStyle='#d1a878';ctx.beginPath();ctx.arc(p.x,p.y-19,6,0,7);ctx.fill();ctx.fillStyle='#65d8ae';ctx.beginPath();ctx.moveTo(p.x-8,p.y-15);ctx.lineTo(p.x+8,p.y-15);ctx.lineTo(p.x+9,p.y-3);ctx.lineTo(p.x-9,p.y-3);ctx.closePath();ctx.fill();ctx.fillStyle='#223638';ctx.fillRect(p.x-6,p.y-4,5,8);ctx.fillRect(p.x+2,p.y-4,5,8);if(player.swing>0){ctx.save();ctx.translate(p.x,p.y-12);ctx.rotate(face);ctx.strokeStyle='#d8ff6b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(4,0,28,-.85,.85);ctx.stroke();ctx.restore()}}
}
function marker(pos,color,label,pulse=true){let p=scr(pos.x,pos.y);let k=pulse?1+Math.sin(elapsed*4)*.12:1;ctx.save();ctx.translate(p.x,p.y-35);ctx.scale(k,k);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.globalAlpha=.85;ctx.beginPath();ctx.arc(0,0,11,0,7);ctx.stroke();ctx.beginPath();ctx.moveTo(0,13);ctx.lineTo(-5,5);ctx.lineTo(5,5);ctx.closePath();ctx.fill();ctx.font='9px DM Mono,monospace';ctx.textAlign='center';ctx.fillText(label,0,-18);ctx.restore()}
function drawWeather(dt){if(weather===2)return;let count=weather===0?110:74;ctx.save();ctx.globalAlpha=weather===0?.34:.68;for(let i=0;i<count;i++){let x=(i*173+elapsed*(weather===0?390:28))%(W+80)-40,y=(i*97+elapsed*(weather===0?650:52))%(H+80)-40;ctx.strokeStyle=weather===0?'#b7d9de':'#f1f5e8';ctx.lineWidth=weather===0?1:.9;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(weather===0?-5:2),y+(weather===0?13:7));ctx.stroke()}ctx.restore()}
function drawWorld(){drawGround();let objects=[];for(const b of world.buildings)objects.push({d:b.x+b.y+b.w+b.h,fn:()=>drawBuilding(b)});for(const t of world.trees)objects.push({d:t.x+t.y,fn:()=>drawTree(t)});for(const c of world.crates)if(!c.used)objects.push({d:c.x+c.y,fn:()=>drawCrate(c)});for(const c of world.cars)objects.push({d:c.x+c.y,fn:()=>drawCar(c)});for(const e of world.enemies)if(e.alive)objects.push({d:e.x+e.y,fn:()=>drawActor(e.x,e.y,'enemy')});if(!courier.found)objects.push({d:courier.x+courier.y,fn:()=>drawActor(courier.x,courier.y,'player')});if(!player.car)objects.push({d:player.x+player.y,fn:()=>drawActor(player.x,player.y,'player',player.face)});objects.sort((a,b)=>a.d-b.d);for(const o of objects)o.fn();
 if(!courier.found)marker(courier,'#d8ff6b','COURIER');if(quest===1)marker(rift,'#9b95ff','RIFT');
 // vignette and scene lighting
 let g=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.18,W/2,H/2,Math.max(W,H)*.72);g.addColorStop(0,'transparent');g.addColorStop(1,'#080f10aa');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);drawWeather(.016);
}

